package pluginapi

import (
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"os"
	"strings"
	"sync"
	"time"
)

const AuditPrefix = "plugin_audit "

type NetworkPolicy string

const (
	NetworkNone      NetworkPolicy = "none"
	NetworkAllowlist NetworkPolicy = "allowlist"

	// Deprecated: NetworkEgress is no longer accepted by the host manifest
	// (which supports only none/allowlist). It is retained solely for SDK
	// source compatibility and is never generated by the host.
	NetworkEgress NetworkPolicy = "egress"
)

type pluginAuditEvent struct {
	Action      string `json:"action"`
	Destination string `json:"destination"`
	Policy      string `json:"policy"`
	Reason      string `json:"reason"`
	Timestamp   string `json:"timestamp"`
}

var auditWriteMu sync.Mutex

func NewGuardedHTTPClient(policy NetworkPolicy, allowlist []string) *http.Client {
	policy = normalizeNetworkPolicy(policy)
	guard := &networkGuard{policy: policy, allowlist: allowlist}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	baseDialer := &net.Dialer{Timeout: 10 * time.Second}
	transport.DialContext = func(ctx context.Context, network, address string) (net.Conn, error) {
		ips, err := guard.check(ctx, address)
		if err != nil {
			return nil, err
		}
		_, port, err := net.SplitHostPort(address)
		if err != nil {
			return nil, err
		}
		var lastErr error
		for _, ip := range ips {
			conn, dialErr := baseDialer.DialContext(ctx, network, net.JoinHostPort(ip.String(), port))
			if dialErr == nil {
				return conn, nil
			}
			lastErr = dialErr
		}
		if lastErr != nil {
			return nil, lastErr
		}
		return nil, fmt.Errorf("no addresses resolved for %q", address)
	}
	return &http.Client{Transport: transport}
}

type networkGuard struct {
	policy    NetworkPolicy
	allowlist []string
	resolver  func(context.Context, string) ([]net.IP, error)
}

func (g *networkGuard) check(ctx context.Context, address string) ([]net.IP, error) {
	host, port, err := net.SplitHostPort(address)
	if err != nil {
		return nil, err
	}
	var reason string
	if IsForbiddenHost(host) {
		reason = "destination is a loopback, metadata or internal host"
	}
	switch g.policy {
	case NetworkNone:
		reason = "outbound network is disabled"
	case NetworkAllowlist:
		if reason == "" && !MatchAllowlist(g.allowlist, host, port) {
			reason = "destination is not in allowlist"
		}
	case NetworkEgress:
		if reason == "" {
			if ip := net.ParseIP(host); ip != nil && IsForbiddenIP(ip) {
				reason = "destination resolves to a forbidden address"
			}
		}
	}
	var ips []net.IP
	if reason == "" && (g.policy == NetworkEgress || g.policy == NetworkAllowlist) {
		resolver := g.resolver
		if resolver == nil {
			resolver = func(c context.Context, h string) ([]net.IP, error) { return net.DefaultResolver.LookupIP(c, "ip", h) }
		}
		addresses, resolveErr := resolver(ctx, host)
		if resolveErr != nil {
			reason = "DNS resolution failed"
		} else {
			for _, resolved := range addresses {
				if IsForbiddenIP(resolved) {
					reason = "destination resolves to a forbidden address"
					break
				}
			}
			ips = addresses
		}
	}
	if reason == "" {
		return ips, nil
	}
	g.emitAudit(address, reason)
	return nil, fmt.Errorf("plugin network blocked: %s", reason)
}

func (g *networkGuard) emitAudit(address, reason string) {
	event := pluginAuditEvent{Action: "network_denied", Destination: address, Policy: string(g.policy), Reason: reason, Timestamp: time.Now().UTC().Format(time.RFC3339Nano)}
	line, err := json.Marshal(event)
	if err != nil {
		return
	}
	auditWriteMu.Lock()
	defer auditWriteMu.Unlock()
	_, _ = fmt.Fprintf(os.Stderr, "%s%s\n", AuditPrefix, line)
}

const (
	EnvNetworkPolicy     = "WEKNORA_PLUGIN_NETWORK_POLICY"
	EnvNetworkAllowlist  = "WEKNORA_PLUGIN_NETWORK_ALLOWLIST"
	EnvEgressProxySocket = "WEKNORA_PLUGIN_EGRESS_SOCKET"
)

func EgressProxySocketFromEnv() string { return strings.TrimSpace(os.Getenv(EnvEgressProxySocket)) }
func PolicyFromEnv() NetworkPolicy {
	return normalizeNetworkPolicy(NetworkPolicy(strings.TrimSpace(os.Getenv(EnvNetworkPolicy))))
}
func normalizeNetworkPolicy(policy NetworkPolicy) NetworkPolicy {
	switch policy {
	case NetworkNone, NetworkEgress, NetworkAllowlist:
		return policy
	default:
		return NetworkNone
	}
}
func AllowlistFromEnv() []string {
	raw := strings.TrimSpace(os.Getenv(EnvNetworkAllowlist))
	if raw == "" {
		return nil
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func NewPluginHTTPClient() *http.Client {
	policy, allowlist, socket := PolicyFromEnv(), AllowlistFromEnv(), EgressProxySocketFromEnv()
	if socket == "" {
		return NewGuardedHTTPClient(policy, allowlist)
	}
	// OCI mode: the host-side egress proxy is the authoritative policy
	// boundary. The SDK only forwards requests to it and does not re-run a
	// full policy check — the container has no network namespace of its own,
	// so the proxy is the only exit and the only place policy is enforced.
	transport := http.DefaultTransport.(*http.Transport).Clone()
	proxyURL := &url.URL{Scheme: "http", Host: "weknora-egress"}
	transport.Proxy = http.ProxyURL(proxyURL)
	transport.DialContext = func(ctx context.Context, _, _ string) (net.Conn, error) {
		return (&net.Dialer{Timeout: 10 * time.Second}).DialContext(ctx, "unix", socket)
	}
	return &http.Client{Transport: transport}
}
